    <q-card class="validation-report-panel">
      <q-card-section class="row items-center q-pa-md report-header">
        <div class="col">
          <h3 class="report-title">
            <span class="report-title-icon" aria-hidden="true">
              <Icon icon="mdi:shield-search" width="22" height="22" />
            </span>
            {{ $t('validation_report_title') }}
          </h3>
          <div v-if="report" class="report-meta">
            <span v-if="report.xrechnung_type" class="meta-chip">
              {{ report.xrechnung_type }}
            </span>
            <span v-if="report.syntax" class="meta-chip">{{ report.syntax }}</span>
            <span v-if="report.profile" class="meta-chip">{{ report.profile }}</span>
            <span v-if="report.version" class="meta-chip">v{{ report.version }}</span>
            <span
