                report.is_valid
                  ? $t('validation_is_valid')
                  : $t('validation_is_invalid')
              }}
            </span>
          </div>
        </div>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-card-section>

      <q-separator />

      <div class="layer-tabs-shell">
        <q-tabs
