<script lang="ts">
import { defineComponent, type PropType } from 'vue';

import {
  LAYER_LABEL_KEY,
  SEVERITY_COLOR,
  SEVERITY_ICON,
  SEVERITY_LABEL_KEY,
  VALIDATION_LAYERS,
  type ValidationFinding,
  type ValidationLayer,
  type ValidationReport,
} from 'src/types/validationReport';

export interface LayerCount {
  errors: number;
  warnings: number;
  info: number;
}

export default defineComponent({
  name: 'ValidationReportPanel',
  props: {
    modelValue: {
      type: Boolean,
      default: false,
    },
    report: {
      type: Object as PropType<ValidationReport | null>,
      default: null,
    },
  },
  emits: ['update:modelValue'],
  data() {
    return {
      activeLayer: 'L1' as ValidationLayer,
      VALIDATION_LAYERS,
      LAYER_LABEL_KEY,
      SEVERITY_LABEL_KEY,
      SEVERITY_ICON,
      SEVERITY_COLOR,
    };
  },
  computed: {
    model: {
      get(): boolean {
        return this.modelValue;
      },
      set(v: boolean) {
        this.$emit('update:modelValue', v);
      },
    },
  },
  watch: {
    report: {
      immediate: true,
      handler(r: ValidationReport | null) {
        if (!r) return;
        // Auto-focus the first layer with findings; fall back to L1.
        const firstFailing = VALIDATION_LAYERS.find((layer) => {
          const counts = this.layerCounts(layer);
          return counts.errors > 0 || counts.warnings > 0;
        });
        this.activeLayer = firstFailing ?? 'L1';
      },
    },
  },
  methods: {
    layerCounts(layer: ValidationLayer): LayerCount {
      const summary = this.report?.summary?.[layer];
      if (summary) {
        return {
          errors: summary.errors,
          warnings: summary.warnings,
          info: summary.info,
        };
      }
      return { errors: 0, warnings: 0, info: 0 };
    },
    layerFindings(layer: ValidationLayer): ValidationFinding[] {
      if (!this.report) return [];
      return this.report.findings.filter((f) => f.layer === layer);
    },
    layerTabClass(layer: ValidationLayer): string {
      const c = this.layerCounts(layer);
      if (c.errors > 0) return 'tab-has-errors';
      if (c.warnings > 0) return 'tab-has-warnings';
      return 'tab-clean';
    },
  },
});
</script>

